func TestConcurrentAllow(t *testing.T) {
	clock := newFakeClock(time.Unix(1700000000, 0))
	l, err := NewWithClock(1000, 100, clock)
	if err != nil {
		t.Fatalf("NewWithClock: %v", err)
	}
	var (
		wg       sync.WaitGroup
		mu       sync.Mutex
		allowed  int
	)
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if l.Allow() {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if allowed != 100 {
		t.Fatalf("allowed = %d, want 100", allowed)
	}
}
